/* global Office, OfficeRuntime, Excel, document, console, fetch, FileReader, localStorage */

const STAMP_STORAGE_KEY = "office-web-stamp.imageDataUrl";
const DEFAULT_STAMP_URL = "assets/default-stamp.png";
const STAMP_SIZE_MM = 12;
const MM_TO_POINTS = 72 / 25.4;
const STAMP_SIZE_POINTS = STAMP_SIZE_MM * MM_TO_POINTS;
const MAX_STAMP_FILE_SIZE_BYTES = 1024 * 1024;
const PNG_DATA_URL_PREFIX = "data:image/png;base64,";

const insertButton = document.getElementById("insert-stamp");
const selectButton = document.getElementById("select-stamp");
const clearButton = document.getElementById("clear-stamp");
const fileInput = document.getElementById("stamp-file");
const stampPreview = document.getElementById("stamp-preview");
const statusText = document.getElementById("status");

let currentStampDataUrl;
let defaultStampDataUrl;

Office.onReady(async (info) => {
  if (info.host !== Office.HostType.Excel) {
    setStatus("このアドインは Excel で使用してください。");
    return;
  }

  selectButton.disabled = false;
  selectButton.addEventListener("click", () => fileInput.click());
  clearButton.addEventListener("click", clearStoredStamp);
  fileInput.addEventListener("change", handleStampFileSelected);
  insertButton.addEventListener("click", insertStampIntoActiveCell);
  await loadStoredStamp();
});

async function insertStampIntoActiveCell() {
  if (!currentStampDataUrl) {
    setStatus("先に押印画像を選択してください。");
    return;
  }

  insertButton.disabled = true;
  setStatus("押印画像を挿入しています。");

  try {
    const stampBase64 = dataUrlToBase64(currentStampDataUrl);

    await Excel.run(async (context) => {
      const range = context.workbook.getSelectedRange();
      range.load(["height", "left", "top", "width"]);
      await context.sync();

      const sheet = context.workbook.worksheets.getActiveWorksheet();
      const shape = sheet.shapes.addImage(stampBase64);

      const targetHeight = STAMP_SIZE_POINTS;
      const targetWidth = STAMP_SIZE_POINTS;

      shape.height = targetHeight;
      shape.width = targetWidth;
      shape.left = range.left + (range.width - targetWidth) / 2;
      shape.top = range.top + (range.height - targetHeight) / 2;
      shape.name = `WebStamp_${Date.now()}`;

      await context.sync();
    });

    setStatus("選択中のセルに押印しました。");
  } catch (error) {
    console.error(error);
    setStatus(error instanceof Error ? error.message : "押印に失敗しました。");
  } finally {
    insertButton.disabled = false;
  }
}

async function handleStampFileSelected(event) {
  const [file] = event.target.files;
  if (!file) {
    return;
  }

  if (!isPngFile(file)) {
    setStatus("PNG ファイルを選択してください。");
    fileInput.value = "";
    return;
  }

  if (file.size > MAX_STAMP_FILE_SIZE_BYTES) {
    setStatus("1MB 以下の PNG ファイルを選択してください。");
    fileInput.value = "";
    return;
  }

  try {
    const dataUrl = await fileToDataUrl(file);
    if (!isPngDataUrl(dataUrl)) {
      throw new Error("PNG ファイルを読み込めませんでした。");
    }

    await saveStampDataUrl(dataUrl);
    applyStampDataUrl(dataUrl, { custom: true });
    setStatus("押印画像を保存しました。セルを選択して押印できます。");
  } catch (error) {
    console.error(error);
    setStatus(error instanceof Error ? error.message : "押印画像の保存に失敗しました。");
  } finally {
    fileInput.value = "";
  }
}

async function loadStoredStamp() {
  try {
    const dataUrl = await getStorageItem(STAMP_STORAGE_KEY);
    if (dataUrl) {
      applyStampDataUrl(dataUrl, { custom: true });
      setStatus("保存済みの押印画像を読み込みました。");
      return;
    }

    await applyDefaultStamp();
    setStatus("デフォルトの押印画像を読み込みました。");
  } catch (error) {
    console.error(error);
    insertButton.disabled = true;
    setStatus("押印画像の読み込みに失敗しました。画像を選択してください。");
  }
}

async function saveStampDataUrl(dataUrl) {
  await setStorageItem(STAMP_STORAGE_KEY, dataUrl);
}

async function clearStoredStamp() {
  try {
    await removeStorageItem(STAMP_STORAGE_KEY);
    await applyDefaultStamp();
    setStatus("保存済み画像をクリアしました。デフォルト画像を使用します。");
  } catch (error) {
    console.error(error);
    setStatus(error instanceof Error ? error.message : "押印画像のクリアに失敗しました。");
  }
}

async function applyDefaultStamp() {
  if (!defaultStampDataUrl) {
    defaultStampDataUrl = await loadDefaultStampDataUrl();
  }

  applyStampDataUrl(defaultStampDataUrl, { custom: false });
}

async function loadDefaultStampDataUrl() {
  const response = await fetch(DEFAULT_STAMP_URL);
  if (!response.ok) {
    throw new Error("デフォルト押印画像を読み込めませんでした。");
  }

  return fileToDataUrl(await response.blob());
}

function applyStampDataUrl(dataUrl, options) {
  currentStampDataUrl = dataUrl;
  stampPreview.src = dataUrl;
  stampPreview.hidden = false;
  insertButton.disabled = false;
  clearButton.disabled = !options.custom;
}

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(new Error("押印画像の変換に失敗しました。"));
    reader.readAsDataURL(file);
  });
}

function dataUrlToBase64(dataUrl) {
  if (!isPngDataUrl(dataUrl)) {
    throw new Error("押印画像の形式が不正です。PNG 画像を選択してください。");
  }

  return dataUrl.slice(PNG_DATA_URL_PREFIX.length);
}

function isPngFile(file) {
  return file.type === "image/png" || file.name.toLowerCase().endsWith(".png");
}

function isPngDataUrl(dataUrl) {
  return dataUrl.startsWith(PNG_DATA_URL_PREFIX);
}

async function getStorageItem(key) {
  if (typeof OfficeRuntime !== "undefined" && OfficeRuntime.storage) {
    return OfficeRuntime.storage.getItem(key);
  }

  return localStorage.getItem(key);
}

async function setStorageItem(key, value) {
  if (typeof OfficeRuntime !== "undefined" && OfficeRuntime.storage) {
    await OfficeRuntime.storage.setItem(key, value);
    return;
  }

  localStorage.setItem(key, value);
}

async function removeStorageItem(key) {
  if (typeof OfficeRuntime !== "undefined" && OfficeRuntime.storage) {
    await OfficeRuntime.storage.removeItem(key);
    return;
  }

  localStorage.removeItem(key);
}

function setStatus(message) {
  statusText.textContent = message;
}
